import React, { useState } from 'react';
import axios from 'axios';

function AuthModal({ onLogin, apiBase }) {
  const [loginTab, setLoginTab] = useState(true);
  const [loginUsername, setLoginUsername] = useState('admin');
  const [loginPassword, setLoginPassword] = useState('admin123');
  const [registerUsername, setRegisterUsername] = useState('');
  const [registerPassword, setRegisterPassword] = useState('');
  const [error, setError] = useState('');

  const useDemoAccount = (username, password) => {
    setLoginTab(true);
    setError('');
    setLoginUsername(username);
    setLoginPassword(password);
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post(`${apiBase}/auth/login`, {
        username: loginUsername,
        password: loginPassword
      });
      onLogin(res.data.access_token, res.data.user);
    } catch (err) {
      setError('Login failed: ' + (err.response?.data?.detail || err.message));
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post(`${apiBase}/auth/register`, {
        username: registerUsername,
        password: registerPassword
      });
      onLogin(res.data.access_token, res.data.user);
    } catch (err) {
      setError('Registration failed: ' + (err.response?.data?.detail || err.message));
    }
  };

  return (
    <div className="auth-modal">
      <div className="auth-container">
        <section className="auth-hero-side">
          <p className="auth-kicker">Marketplace Access</p>
          <h1 className="auth-title">Agent Workspace</h1>
          <p className="auth-subtitle">
            Run strict LLM agents for analytics, database help, reporting, customer insights, sales, and pricing.
          </p>

          <div className="auth-feature-list">
            <div className="auth-feature-item">Strict role-based responses</div>
            <div className="auth-feature-item">Live demo attempt tracking</div>
            <div className="auth-feature-item">Purchase-to-unlock access keys</div>
          </div>

          <div className="auth-demo-block">
            <p className="auth-demo-title">Quick demo accounts</p>
            <div className="auth-demo-actions">
              <button type="button" className="auth-demo-btn" onClick={() => useDemoAccount('admin', 'admin123')}>
                Use admin
              </button>
              <button type="button" className="auth-demo-btn" onClick={() => useDemoAccount('user1', 'user123')}>
                Use user1
              </button>
            </div>
          </div>
        </section>

        <section className="auth-form-side">
          <div className="auth-tabs">
            <button
              className={`auth-tab ${loginTab ? 'active' : ''}`}
              onClick={() => setLoginTab(true)}
            >
              Login
            </button>
            <button
              className={`auth-tab ${!loginTab ? 'active' : ''}`}
              onClick={() => setLoginTab(false)}
            >
              Register
            </button>
          </div>

          {error && <div className="auth-error">{error}</div>}

          {loginTab ? (
            <form className="auth-form active" onSubmit={handleLogin}>
              <label className="auth-label" htmlFor="login-username">Username</label>
              <input
                id="login-username"
                type="text"
                placeholder="Enter username"
                value={loginUsername}
                onChange={(e) => setLoginUsername(e.target.value)}
                required
              />
              <label className="auth-label" htmlFor="login-password">Password</label>
              <input
                id="login-password"
                type="password"
                placeholder="Enter password"
                value={loginPassword}
                onChange={(e) => setLoginPassword(e.target.value)}
                required
              />
              <button type="submit">Login</button>
              <p className="auth-helper">
                Use quick demo buttons or login with your registered account.
              </p>
            </form>
          ) : (
            <form className="auth-form active" onSubmit={handleRegister}>
              <label className="auth-label" htmlFor="register-username">Username</label>
              <input
                id="register-username"
                type="text"
                placeholder="Choose username"
                value={registerUsername}
                onChange={(e) => setRegisterUsername(e.target.value)}
                required
              />
              <label className="auth-label" htmlFor="register-password">Password</label>
              <input
                id="register-password"
                type="password"
                placeholder="Choose password"
                value={registerPassword}
                onChange={(e) => setRegisterPassword(e.target.value)}
                required
              />
              <button type="submit">Create Account</button>
            </form>
          )}

          <div className="auth-footer-note">
            Every app start opens this login screen first. Your demo limits and purchases are account-based.
          </div>
        </section>
      </div>
    </div>
  );
}

export default AuthModal;
